<section class="panel"><div class="section-heading"><div><h3>Ordens recentes</h3><p>Acompanhamento do fluxo</p></div><a class="text-link" href="<?= e($baseUrl) ?>/ordens">Ver todas →</a></div><?php if(!$recentOrders): ?><div class="table-empty">Nenhuma ordem cadastrada.</div><?php else: ?><div class="compact-list"><?php foreach($recentOrders as $o): ?><a href="<?= e($baseUrl) ?>/ordens/<?= (int)$o['id'] ?>"><b>O.S. - <?= str_pad((string)$o['order_number'],4,'0',STR_PAD_LEFT) ?></b><span><?= e($o['service_type']) ?></span><em class="state-pill"><?= e($o['status']) ?></em></a><?php endforeach; ?></div><?php endif; ?></section></div>
